"""Ficha 17 · Pielonefritis e ITU febril del adulto (borrador 27/11/2026).
Fuentes: EAU 2025-2026 (clasificación localizada/sistémica), EAU 2024 (Kranz, Eur Urol 2024: dosis y duración),
SEIMC 2017 (de Cueto, EIMC 2017: criterios ambulatorios, BLEE, resistencias en España), IDSA 2025 (duración).
python3 tools/pielonefritis.py <dir_salida>"""
from _comun_2511 import *
T="PIELONEFRITIS"; N=7; V="#1E8C45"   # franja verde: frecuente
KW=dict(strip=V)
pg=lambda *a,**k: page(*a,**KW,**k)
P=[
pg(1,N,T,big("PIELONEFRITIS E ITU FEBRIL",128)+big(f'YA NO ES COMPLICADA O NO: <span style="color:{R}">ES SISTÉMICA</span>',104)+'<div style="font-size:40px;font-weight:600;line-height:1.3;max-width:860px">Cómo se clasifica ahora, qué pedir, quién se va a casa, qué antibiótico y cuántos días. Con ficha final.</div>',cover=True),
pg(2,N,T,kicker("1 · CLASIFICA (EAU 2025)")+big("¿LOCALIZADA<br>O SISTÉMICA?",112)+rows(row("Localizada","Cistitis sin signos sistémicos"),row("Sistémica","Fiebre o hipotermia, escalofríos"),row("","Delirium, hipotensión, taquicardia"),row("","Dolor o puñopercusión lumbar"))+red("Nitrofurantoína y fosfomicina oral no sirven en la sistémica")+note("Los factores de riesgo (sonda, litiasis, obstrucción, inmunosupresión, embarazo) se valoran aparte.")),
pg(3,N,T,kicker("2 · QUÉ PEDIR")+big("UROCULTIVO",190,R,True)+rows(row("Urocultivo","Siempre, antes del antibiótico"),row("2 hemocultivos","Si sepsis o enfermedad grave"),row("Ecografía","Litiasis, función renal alterada o pH urinario alto"),row("TC","Fiebre a las 72 h o empeora"))+red("Obstruida e infectada: drenaje urgente")+note("La ecografía busca dilatación de la vía; sin obstrucción, la imagen no cambia el antibiótico.")),
pg(4,N,T,kicker("3 · ¿A CASA? TRATAMIENTO ORAL")+big("FIEBRE &lt; 39 °C",160,R,True)+rows(row("Alta si","Sin vómitos, dolor intenso ni sepsis"),row("Ciprofloxacino","500–750 mg/12 h, 7 días"),row("Levofloxacino","750 mg/24 h, 5 días"),row("Cefalosporina oral","Cefpodoxima o ceftibuteno, 10 días"))+red("Quinolona solo si la resistencia local es &lt; 10 %")+note("Con betalactámico oral o cotrimoxazol de inicio, pon antes una dosis IV de ceftriaxona. Ajusta al antibiograma.")),
pg(5,N,T,kicker("4 · INGRESO: TRATAMIENTO IV")+big("CEFTRIAXONA",190,R,True)+rows(row("Sin riesgo","Ceftriaxona 1–2&nbsp;g/24&nbsp;h"),row("Riesgo de BLEE","Ertapenem 1&nbsp;g/24&nbsp;h"),row("Shock o ligada a cuidados","Meropenem 1&nbsp;g/8&nbsp;h"),row("En shock, valora","+ amikacina 15&nbsp;mg/kg/24&nbsp;h"))+red("En la urosepsis, cubre BLEE de entrada")+note("Riesgo de BLEE: aislamiento previo en orina, antibiótico reciente, sonda o manipulación urológica.")),
pg(6,N,T,kicker("5 · CUÁNTOS DÍAS")+big("7 DÍAS",250,R,True)+rows(row("Quinolona","5–7 días"),row("Otro antibiótico","7–10 días según el fármaco"),row("Con bacteriemia","Igual si mejora (IDSA 2025)"),row("Varón con fiebre","Hasta 14 días si puede ser prostatitis"))+note("Paso a oral cuando mejora, tolera y hay opción eficaz en el antibiograma. Sin urocultivo de control si se resuelve.")),
pg(7,N,T,ficha_body("PIELONEFRITIS","Adulto",[("CLASIFICA","Sistémica: fiebre, escalofríos, delirium, hipotensión, taquicardia o dolor lumbar"),("PIDE","Urocultivo siempre. 2 hemocultivos si sepsis. Eco si litiasis o fallo renal"),("OBSTRUCCIÓN","Obstruida e infectada: drenaje urgente",True),("A CASA","Fiebre &lt; 39 °C, sin vómitos, dolor ni sepsis. Quinolona si resistencia &lt; 10 % o ceftriaxona IV + cefalosporina oral"),("INGRESO","Ceftriaxona 1–2 g/24 h. Riesgo BLEE: ertapenem 1&nbsp;g/24&nbsp;h"),("SHOCK","Meropenem 1 g/8 h ± amikacina 15 mg/kg/24 h",True),("DURACIÓN","Quinolona 5–7 d; otros 7–10 d. Varón febril: hasta 14 d"),("NO","Nitrofurantoína ni fosfomicina oral. Bacteriuria sin síntomas: no tratar")],"EAU Guidelines on Urological Infections 2025-2026; Kranz J, et al. Eur Urol 2024;86:27-41; de Cueto M, et al. (SEIMC) EIMC 2017;35:314-20; Trautner BW, et al. (IDSA) Clin Infect Dis 2025",size=124,fs=26),ficha="17"),
]
render(P,sys.argv[1] if len(sys.argv)>1 else "out","pielonefritis")
